SELECT s.settlement_id AS settlementId, s.settlement_no AS settlementNo, u.nick_name AS authorName, s.order_count AS orderCount, s.total_amount AS totalAmount, s.platform_amount AS platformAmount, s.author_amount AS authorAmount, s.platform_ratio AS platformRatio, s.status, DATE_FORMAT(s.settlement_time, '%Y-%m-%d %H:%i') AS settlementTime, DATE_FORMAT(s.create_time, '%Y-%m-%d %H:%i') AS createTime FROM sys_settlement s LEFT JOIN sys_user u ON s.author_id = u.user_id
AND s.status = #{status}
AND s.create_time >= #{startDate}
AND s.create_time <= #{endDate}
AND (s.settlement_no LIKE CONCAT('%', #{keyword}, '%') OR u.nick_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY s.create_time DESC LIMIT #{offset}, #{limit}

